async def get_static_post(db) -> tuple[str, str] | None:
    """Возвращает (тема, текст) поста, которого ещё не было (дедуп в posted_news).

    Полный круг без повторов; после исчерпания банка ключи sp: чистятся
    (кроме полл-таймстемпов) и цикл начинается заново — с повторной попыткой
    подбора (раунд 13: раньше после сброса возвращали None, теряя один цикл).
    """
    from bot.post_utils import title_fingerprint

    for _ in range(len(STATIC_POSTS) + 1):
        idx = _next_index()
        topic, text = STATIC_POSTS[idx % len(STATIC_POSTS)]
        fp = _fingerprint(topic)
        if not await db.is_news_posted(_PREFIX + fp):
            return topic, text
        # Прошли все посты и все «уже публиковались» → сброс дедупа, цикл заново
        if _ >= len(STATIC_POSTS) - 1:
            cleared = await db.delete_posted_keys(_PREFIX)
            logger.info(f"Static posts: bank exhausted — reset {cleared} dedup keys, cycle restarts")
    return None


def mark_key_for_topic(topic: str) -> str:
    """Ключ дедупа для пометки post-static topic в posted_news."""
    return _PREFIX + _fingerprint(topic)


_next_i = {"i": 0}


def _next_index() -> int:
    """Простая ротация по кругу (в рамках процесса) — дедуп в БД режет повторы."""
    i = _next_i["i"] % len(STATIC_POSTS)
    _next_i["i"] += 1
    return i


def bank_size() -> int:
    return len(STATIC_POSTS)


def min_static_len() -> int:
    """Минимальная длина статик-поста (контроль качества при правках банка)."""
    return min(len(t) for _, t in STATIC_POSTS)
